function addBitStrings(a: string, b: string): string {
  let i = a.length - 1, j = b.length - 1, carry = 0;
  const out: number[] = [];
  while (i >= 0 || j >= 0 || carry) {
    let sum = carry;
    if (i >= 0) sum += a.charCodeAt(i--) - 48;
    if (j >= 0) sum += b.charCodeAt(j--) - 48;
    out.push(sum & 1);
    carry = sum >> 1;
  }
  return out.reverse().join("");
}

